addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);function toast(t){let q=document.getElementById('toast');q.textContent=t;q.classList.add('show');clearTimeout(q.t);q.t=setTimeout(()=>q.classList.remove('show'),1600)}
