function draw(){let g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'#17121d');g.addColorStop(.55,'#0b090e');g.addColorStop(1,'#09070a');x.fillStyle=g;x.fillRect(0,0,W,H);drawSky();drawCastle();for(let p of particles){p.life-=.016;p.x+=p.vx*.016;p.y+=p.vy*.016;x.globalAlpha=Math.max(0,p.life*2);x.fillStyle=p.c;x.fillRect(p.x,p.y,3,3)}x.globalAlpha=1;for(let e of enemies){x.save();x.translate(e.x,e.y);x.fillStyle='#17100e';x.beginPath();x.moveTo(-11,-8);x.lineTo(-5,-18);x.lineTo(0,-9);x.lineTo(5,-18);x.lineTo(11,-8);x.lineTo(7,15);x.lineTo(-7,15);x.closePath();x.fill();x.fillStyle='#a7a0b0';x.beginPath();x.arc(-3,-9,1.5,0,7);x.arc(3,-9,1.5,0,7);x.fill();x.strokeStyle='#9b8c65';x.beginPath();x.moveTo(8,-3);x.lineTo(17,9);x.stroke();x.restore()}drawPlayer();}
function drawSky(){x.fillStyle='rgba(155,151,174,.12)';for(let i=0;i<18;i++){let xx=(i*137)%W,yy=(i*83)%Math.floor(H*.5);x.fillRect(xx,yy,1,1)}x.fillStyle='#d0c7ae';x.beginPath();x.arc(W*.78,H*.15,26,0,7);x.fill();x.fillStyle='#17121d';x.beginPath();x.arc(W*.78-10,H*.15-8,28,0,7);x.fill()}
